#!/bin/bash
# Checks the translated metadata generated by the build.
# Usage: i18n-metadata.sh <desktop> <autostart> <metainfo> <policy>
set -eu
desktop=$1 autostart=$2 metainfo=$3 policy=$4
fail() { echo "FAIL: $*"; exit 1; }
grep -qx 'Name=Mainuan Welcome' "$desktop" || fail "English Name missing in $desktop"
grep -qx 'Name\[pt_BR\]=Boas-vindas do Mainuan' "$desktop" || fail "pt_BR Name missing in $desktop"
grep -qx 'Comment\[pt_BR\]=Configure e conheça o Mainuan' "$desktop" || fail "pt_BR Comment missing in $desktop"
grep -q '^Keywords\[pt_BR\]=boas-vindas;' "$desktop" || fail "pt_BR Keywords missing in $desktop"
grep -qx 'Exec=mainuan-welcome' "$desktop" || fail "Exec changed in $desktop"
grep -qx 'Comment\[pt_BR\]=Mostra as boas-vindas do Mainuan ao iniciar a sessão' "$autostart" || fail "pt_BR Comment missing in $autostart"
grep -qx 'X-KDE-autostart-phase=2' "$autostart" || fail "autostart keys changed"
grep -q '<summary xml:lang="pt-BR">Configure o Mainuan e conheça os recursos do seu desktop</summary>' "$metainfo" \
    || fail "pt-BR summary missing in $metainfo"
# Release notes and the developer name are deliberately not translated.
if grep -q '<release.*xml:lang\|<p xml:lang="[^"]*">First official' "$metainfo"; then fail "release notes were translated"; fi
# polkit looks translations up by POSIX locale name (pt_BR, then pt): no BCP 47 tags.
grep -q '<message xml:lang="pt_BR">É necessário autenticar-se' "$policy" || fail "pt_BR polkit message missing"
grep -q '<description xml:lang="pt_BR">' "$policy" || fail "pt_BR polkit description missing"
if grep -Eq 'xml:lang="[a-z]{2,3}-' "$policy"; then fail "BCP 47 xml:lang in $policy"; fi
grep -q '<action id="org.mainuan.welcome.install">' "$policy" || fail "polkit action id changed"
grep -q 'org.freedesktop.policykit.exec.path">/.*/mainuan-welcome-helper<' "$policy" || fail "helper path not configured"
echo "translated metadata OK"
